  "help.chitDiscount": "ਨਿਲਾਮੀ ਵਿੱਚ ਤੁਸੀਂ ਪੂਰੇ ਚਿਟ ਮੁੱਲ ਤੋਂ ਘੱਟ ਸਵੀਕਾਰ ਕਰਦੇ ਹੋ — ਇਹ ਛੋਟ ਦੂਜੇ ਮੈਂਬਰਾਂ ਨਾਲ ਸਾਂਝੀ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਤੁਹਾਨੂੰ ਕਦੇ ਵੀ ਪੂਰੀ ਚਿੱਟ ਰਕਮ ਨਕਦ ਵਿੱਚ ਨਹੀਂ ਮਿਲਦੀ।",
  "help.chitAdvisor": "ਉਹਨਾਂ ਮਹੀਨਿਆਂ ਦੀ ਤੁਲਨਾ ਕਰੋ ਜਦੋਂ ਤੁਸੀਂ ਚਿੱਟ ਲੈ ਸਕਦੇ ਹੋ: ਅੰਦਾਜ਼ਨ ਛੋਟ, ਫੋਰਮੈਨ ਤੋਂ ਬਾਅਦ ਭੁਗਤਾਨ, ਉਸ ਮਹੀਨੇ ਦੇ ਤੁਹਾਡੇ ਦੂਜੇ ਬਿੱਲ, ਅਤੇ ਵੱਧ ਤੋਂ ਵੱਧ ਨੁਕਸਾਨ ਜੋ ਤੁਸੀਂ ਸਵੀਕਾਰ ਕਰਨ ਲਈ ਤਿਆਰ ਹੋ।",
  "help.chitMaxLoss": "ਅਸੀਂ ਤੁਹਾਡੀ ਆਮਦਨੀ, ਮਹੀਨਾਵਾਰ ਬਕਾਇਆ, ਖੁੱਲ੍ਹੇ ਕਰਜ਼ੇ, ਬਕਾਇਆ ਬਿੱਲਾਂ, ਅਤੇ ਬੱਚਤਾਂ ਤੋਂ ਵੱਧ ਤੋਂ ਵੱਧ ਨੁਕਸਾਨ ਦਾ ਸੁਝਾਅ ਦਿੰਦੇ ਹਾਂ - ਇੱਕ ਨਿਸ਼ਚਿਤ% ਨਹੀਂ। ਜਲਦੀ ਲੈਣਾ ਅਕਸਰ ਇਸ ਤੋਂ ਵੱਧ ਜਾਂਦਾ ਹੈ; ਬਾਅਦ ਦੇ ਮਹੀਨੇ ਆਮ ਤੌਰ 'ਤੇ ਘੱਟ ਖਰਚ ਹੁੰਦੇ ਹਨ।",
  "help.loanExtraTiming": "ਆਉਣ ਵਾਲੇ ਮਹੀਨਿਆਂ ਨੂੰ ਦਿਖਾਉਂਦਾ ਹੈ: ਜਦੋਂ ਹੋਰ ਬਿੱਲ ਹਲਕੇ ਹੁੰਦੇ ਹਨ ਤਾਂ ਜੋ ਤੁਸੀਂ ਇਸ ਕਰਜ਼ੇ 'ਤੇ ਵਾਧੂ ਭੁਗਤਾਨ ਕਰ ਸਕੋ, ਅਤੇ ਭਾਰੀ ਮਹੀਨੇ ਜਦੋਂ ਤੁਹਾਨੂੰ ਘੱਟੋ-ਘੱਟ 'ਤੇ ਬਣੇ ਰਹਿਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "help.incomeEntryBasis": "ਟੇਕ-ਹੋਮ ਟੈਕਸ, PF, ਅਤੇ ਨਿਸ਼ਚਿਤ ਕਟੌਤੀਆਂ ਤੋਂ ਬਾਅਦ ਤੁਹਾਡੇ ਬੈਂਕ ਵਿੱਚ ਆਉਣ ਵਾਲੀਆਂ ਚੀਜ਼ਾਂ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ — ਦਬਾਅ ਅਤੇ ਮੁਫਤ-ਨਕਦੀ ਗਣਿਤ ਲਈ ਸਭ ਤੋਂ ਵਧੀਆ। ਕੁੱਲ ਸਿਰਫ਼ ਉਦੋਂ ਹੀ ਲਾਭਦਾਇਕ ਹੈ ਜੇਕਰ ਤੁਸੀਂ ਦਾਖਲ ਕੀਤੇ ਗਏ ਹਰੇਕ ਨੰਬਰ ਨੂੰ ਪ੍ਰੀ-ਟੈਕਸ ਹੈ; ਮੁਫ਼ਤ ਨਕਦੀ ਤੁਹਾਡੇ ਅਸਲ ਬੈਂਕ ਬੈਲੇਂਸ ਨਾਲੋਂ ਘੱਟ ਦਿਖਾਈ ਦੇ ਸਕਦੀ ਹੈ ਜੇਕਰ ਘਰ ਲੈ ਜਾਣ ਦੀ ਆਮਦਨ ਕੁੱਲ ਤੋਂ ਘੱਟ ਹੈ।",
  "help.householdPayerBillTag": "ਪਰਿਵਾਰਕ ਮੋਡ ਲਈ ਵਿਕਲਪਿਕ: ਭੁਗਤਾਨ ਕਰਨ ਵਾਲੇ ਨੂੰ ਟੈਗ ਕਰੋ ਤਾਂ ਜੋ ਘਰੇਲੂ ਨਬਜ਼ ਵੰਡੀ ਜ਼ਿੰਮੇਵਾਰੀ ਦਾ ਵਰਣਨ ਕਰ ਸਕੇ। ਕੁੱਲ ਅਤੇ ਦਬਾਅ ਦਾ ਗਣਿਤ ਇੱਕੋ ਜਿਹਾ ਰਹਿੰਦਾ ਹੈ।",
