  "support.about": "ਬਾਰੇ CommitTrack",
  "support.aboutBody": "CommitTrack ਭਾਰਤੀ ਪਰਿਵਾਰਾਂ ਨੂੰ ਬਿੱਲਾਂ, ਉਧਾਰ ਦੇਣ ਅਤੇ ਮਹੀਨਾਵਾਰ ਦਬਾਅ ਨੂੰ ਟਰੈਕ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। Daloy Tech ਦੁਆਰਾ ਬਣਾਇਆ ਗਿਆ, Tadsaya ਦੇ ਅਧੀਨ ਇੱਕ SaaS ਕੰਪਨੀ।",
