  "notifications.unsupported": "ਤੁਹਾਡਾ ਬ੍ਰਾਊਜ਼ਰ ਸੂਚਨਾਵਾਂ ਦਾ ਸਮਰਥਨ ਨਹੀਂ ਕਰਦਾ ਹੈ।",
  "notifications.enabledOk": "ਬ੍ਰਾਊਜ਼ਰ ਸੁਚੇਤਨਾਵਾਂ ਨੂੰ ਚਾਲੂ ਕੀਤਾ ਗਿਆ। ਐਪ ਬੰਦ ਹੋਣ 'ਤੇ ਅਲਰਟ ਲਈ ਹੋਮ ਸਕ੍ਰੀਨ 'ਤੇ ਐਪ ਸ਼ਾਮਲ ਕਰੋ।",
