  "privacy.whyBody": "ਸਿਰਫ਼ ਤੁਹਾਡੇ ਵਿੱਤੀ ਦਬਾਅ ਦੇ ਸਕੋਰ, ਵਚਨਬੱਧਤਾ ਦੇ ਬੋਝ, ਬਚਾਅ ਦੇ ਰਨਵੇ, ਅਤੇ ਉਧਾਰ ਰਿਕਾਰਡਾਂ ਦੀ ਗਣਨਾ ਕਰਨ ਲਈ। ਹੋਰ ਕੋਈ ਮਕਸਦ ਨਹੀਂ।",
  "privacy.whereTitle": "ਜਿੱਥੇ ਇਸਨੂੰ ਸਟੋਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ",
  "privacy.whereBody": "ਮੁੱਖ ਤੌਰ 'ਤੇ ਤੁਹਾਡੀ ਡਿਵਾਈਸ (ਲੋਕਲ ਸਟੋਰੇਜ) 'ਤੇ। ਵਿਕਲਪਿਕ ਤੌਰ 'ਤੇ Supabase ਵਿੱਚ (ਵਿਸ਼ੇਸ਼ ਤੌਰ 'ਤੇ ਏਨਕ੍ਰਿਪਟਡ, ਪ੍ਰਤੀ ਉਪਭੋਗਤਾ ਅਲੱਗ) ਜਦੋਂ ਕਲਾਉਡ ਸਮਕਾਲੀਕਰਨ ਸਮਰਥਿਤ ਹੁੰਦਾ ਹੈ।",
  "privacy.notTitle": "ਅਸੀਂ ਕੀ ਨਹੀਂ ਕਰਦੇ",
  "privacy.notBody": "ਅਸੀਂ ਤੁਹਾਡਾ ਡੇਟਾ ਨਹੀਂ ਵੇਚਦੇ। ਅਸੀਂ ਕ੍ਰੈਡਿਟ ਬਿਊਰੋ ਨਾਲ ਸਾਂਝਾ ਨਹੀਂ ਕਰਦੇ ਹਾਂ। ਅਸੀਂ ਇਸ਼ਤਿਹਾਰਬਾਜ਼ੀ ਲਈ ਡੇਟਾ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕਰਦੇ ਹਾਂ। Razorpay ਭੁਗਤਾਨਾਂ ਨੂੰ ਸੰਭਾਲਦਾ ਹੈ — CommitTrack ਕਦੇ ਵੀ ਤੁਹਾਡੇ ਕਾਰਡ ਦੇ ਵੇਰਵੇ ਨਹੀਂ ਦੇਖਦਾ।",
  "privacy.rightsTitle": "ਤੁਹਾਡੇ ਅਧਿਕਾਰ (DPDP ਐਕਟ 2023)",
  "privacy.rightsAccess": "ਪਹੁੰਚ: Profile → ਐਕਸਪੋਰਟ ਡੇਟਾ",
  "privacy.rightsCorrection": "ਸੁਧਾਰ: ਐਪ ਵਿੱਚ ਸਿੱਧਾ ਸੰਪਾਦਨ ਕਰੋ",
  "privacy.rightsErasure": "ਮਿਟਾਓ: Profile → ਸਾਰਾ ਡਾਟਾ ਮਿਟਾਓ",
  "privacy.rightsGrievance": "ਸ਼ਿਕਾਇਤ: {email}",
  "privacy.retentionTitle": "ਡਾਟਾ ਧਾਰਨ",
  "privacy.retentionLocal": "ਸਥਾਨਕ ਡਾਟਾ: ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਐਪ ਨੂੰ ਨਹੀਂ ਮਿਟਾਉਂਦੇ ਜਾਂ ਸਾਰਾ ਡਾਟਾ ਮਿਟਾਓ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕਰਦੇ।",
  "privacy.retentionCloud": "ਕਲਾਉਡ ਡੇਟਾ: ਖਾਤਾ ਮਿਟਾਉਣ ਦੇ 30 ਦਿਨਾਂ ਦੇ ਅੰਦਰ ਮਿਟਾਇਆ ਜਾਂਦਾ ਹੈ।",
  "privacy.contactTitle": "ਸੰਪਰਕ ਕਰੋ",
  "plans.currentBadge": "ਵਰਤਮਾਨ",
  "sync.backupBullet": "ਬੈਕਅੱਪ ਹੁਣੇ ਤੁਹਾਡੇ ਮੌਜੂਦਾ ਡੇਟਾ ਨੂੰ Supabase ਵਿੱਚ ਸੁਰੱਖਿਅਤ ਕਰਦਾ ਹੈ।",
  "sync.restoreBullet": "ਰੀਸਟੋਰ ਇਸ ਡਿਵਾਈਸ ਨੂੰ ਤੁਹਾਡੇ ਆਖਰੀ ਸੁਰੱਖਿਅਤ ਕੀਤੇ ਬੈਕਅੱਪ ਨਾਲ ਬਦਲ ਦਿੰਦਾ ਹੈ।",
  "sync.autoBullet": "ਆਟੋ-ਬੈਕਅੱਪ ਤੁਹਾਡੇ ਦੁਆਰਾ ਸੰਪਾਦਿਤ ਕਰਨ ਤੋਂ ਕੁਝ ਸਕਿੰਟਾਂ ਬਾਅਦ ਚੱਲਦਾ ਹੈ (ਜਦੋਂ ਯੋਗ ਕੀਤਾ ਜਾਂਦਾ ਹੈ)।",
  "sync.title": "ਖਾਤਾ ਬੈਕਅੱਪ",
  "sync.notConfigured": "Supabase ਕੌਂਫਿਗਰ ਨਹੀਂ ਕੀਤਾ ਗਿਆ ਹੈ। VITE_SUPABASE_URL ਅਤੇ VITE_SUPABASE_ANON_KEY ਸ਼ਾਮਲ ਕਰੋ, ਫਿਰ supabase/migrations/ ਵਿੱਚ ਮਾਈਗ੍ਰੇਸ਼ਨ ਚਲਾਓ।",
  "sync.freePlanBody": "Free ਪਲਾਨ ਸਿਰਫ਼ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਡਾਟਾ ਰੱਖਦਾ ਹੈ। ਆਪਣੇ ਖਾਤੇ ਦੇ ਅਧੀਨ ਇੱਕ ਨਿੱਜੀ Supabase ਬੈਕਅੱਪ ਨੂੰ ਸੁਰੱਖਿਅਤ ਕਰਨ ਲਈ Pro ਜਾਂ Power ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰੋ (ਕਿਸੇ ਵੀ ਸਮੇਂ ਸਮਰੱਥ ਜਾਂ ਅਯੋਗ ਕਰੋ)।",
  "sync.freePlanHint": "ਤੁਸੀਂ ਅਜੇ ਵੀ ਹੇਠਾਂ JSON ਫਾਈਲਾਂ ਨੂੰ ਨਿਰਯਾਤ ਅਤੇ ਆਯਾਤ ਕਰ ਸਕਦੇ ਹੋ।",
  "sync.signInBody": "ਤੁਹਾਡੀ ਯੋਜਨਾ ਵਿੱਚ Supabase ਬੈਕਅੱਪ ਸ਼ਾਮਲ ਹੈ। ਖਾਤੇ ਦੇ ਅਧੀਨ ਸਾਈਨ ਇਨ ਕਰੋ, ਫਿਰ {account} ਦੇ ਅਧੀਨ ਇਸ ਡਿਵਾਈਸ ਦੇ ਡੇਟਾ ਨੂੰ ਸੁਰੱਖਿਅਤ ਕਰਨ ਲਈ ਬੈਕਅੱਪ ਚਾਲੂ ਕਰੋ।",
  "sync.signInHint": "ਸਥਾਨਕ ਡਾਟਾ ਉਦੋਂ ਤੱਕ ਡੀਵਾਈਸ 'ਤੇ ਰਹਿੰਦਾ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਰੀਸਟੋਰ ਕਰਨਾ ਨਹੀਂ ਚੁਣਦੇ।",
  "sync.accountLine": "ਖਾਤਾ: {account} — Supabase (RLS) ਵਿੱਚ ਇੱਕ ਨਿੱਜੀ ਕਤਾਰ। ਸਥਾਨਕ ਸਟੋਰੇਜ ਪ੍ਰਾਇਮਰੀ ਰਹਿੰਦੀ ਹੈ।",
  "sync.toggleTitle": "Supabase ਬੈਕਅੱਪ ਦੀ ਵਰਤੋਂ ਕਰੋ",
  "sync.toggleHint": "ਬੰਦ = ਸਿਰਫ਼ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਸਥਾਨਕ। ਚਾਲੂ = ਆਪਣੇ ਖਾਤੇ ਰਾਹੀਂ ਬੈਕਅੱਪ ਅਤੇ ਰੀਸਟੋਰ ਕਰੋ।",
  "sync.lastBackup": "ਪਿਛਲਾ ਬੈਕਅੱਪ: {when}",
