  "stability.headline.dualIncome": "ਘਰੇਲੂ ਸੰਯੁਕਤ ਆਮਦਨ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਨ — ਕਿਸੇ ਵੀ ਸਰੋਤ ਦੇ ਨੁਕਸਾਨ ਨਾਲ ਦਬਾਅ ਵਧੇਗਾ।",
