  "stability.goalBalance.stagger": "ਕਈ ਟੀਚੇ ਸਰਗਰਮ ਹਨ - ਹੈਰਾਨਕੁਨ ਟੀਚੇ ਇਸ ਲਈ ਇੱਕ ਮੀਲ ਪੱਥਰ ਦੂਜਿਆਂ 'ਤੇ ਤਰੱਕੀ ਨੂੰ ਘੱਟ ਨਹੀਂ ਕਰਦਾ।",
  "insight.goal-overlap": "ਤੁਸੀਂ {count} ਟੀਚਿਆਂ ਨੂੰ ਟਰੈਕ ਕਰ ਰਹੇ ਹੋ ਜਦੋਂ ਕਿ ਮਹੀਨਾਵਾਰ ਬਕਾਇਆ ਆਮਦਨ ਦਾ ਵੱਡਾ ਹਿੱਸਾ ਵਰਤਦਾ ਹੈ — ਤਰੱਕੀ ਸਾਰੇ ਮੋਰਚਿਆਂ 'ਤੇ ਹੌਲੀ ਹੋ ਸਕਦੀ ਹੈ।",
  "insight.goal-edu-wedding": "ਸਿੱਖਿਆ ਅਤੇ ਵਿਆਹ ਜਾਂ ਇਵੈਂਟ ਦੇ ਟੀਚਿਆਂ ਲਈ ਇੱਕ ਸਪੱਸ਼ਟ ਮਾਸਿਕ ਟੁਕੜੇ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ — ਵਿਚਾਰ ਕਰੋ ਕਿ ਪਹਿਲਾਂ ਕਿਹੜਾ ਆਉਂਦਾ ਹੈ।",
  "insight.goal-debt-save": "ਸੀਮਤ ਮੁਫਤ ਨਕਦੀ 'ਤੇ ਕਰਜ਼ੇ ਦਾ ਭੁਗਤਾਨ ਕਰਨਾ ਅਤੇ ਬੱਚਤਾਂ ਨੂੰ ਇਕੱਠਾ ਕਰਨਾ ਮੁਸ਼ਕਲ ਹੈ - ਇੱਕ ਉਦੇਸ਼ ਨੂੰ ਤਰਜੀਹ ਦਿਓ।",
