  "pressure.hint.elevated": "ਅਣਕਿਆਸੇ ਖਰਚਿਆਂ ਲਈ ਸੀਮਤ ਬਫਰ — ਨਵੀਆਂ ਲੰਬੀਆਂ ਵਚਨਬੱਧਤਾਵਾਂ ਨੂੰ ਮੁਲਤਵੀ ਕਰੋ।",
